"""Concurrent decision making with multi-record safety."""

import copy


# Global state to track pending operations
pending_operations = {}

def run(decision_store, operation, value):
    if operation == 'read':
        return copy.deepcopy(decision_store.rows[value])
    elif operation == 'prepare':
        group, actor = value
        # Check if this group has any active actors
        if group not in decision_store.rows:
            return None
        if actor not in decision_store.rows[group]:
            return None
        if not decision_store.rows[group][actor]:
            return None

        # Check if there's at least one other active actor
        active_count = sum(1 for k, v in decision_store.rows[group].items() if k != actor and v)
        if active_count == 0:
            return None

        # Store the preparation result
        preparation_result = (group, actor, decision_store.revisions[group])
        pending_operations[id(preparation_result)] = preparation_result
        return preparation_result
    elif operation == 'commit':
        if value is None:
            return 'conflict'

        group, actor, revision = value
        # Validate the commit against current state
        if group not in decision_store.rows:
            return 'conflict'
        if actor not in decision_store.rows[group]:
            return 'conflict'
        if not decision_store.rows[group][actor]:
            return 'conflict'
        if decision_store.revisions[group] != revision:
            return 'conflict'

        # Commit the change
        decision_store.commit(group, actor)
        return 'committed'
    else:
        raise ValueError(operation)
EOF

